222				// explanation is still useful and should remain available.
223				selected.MetadataMissing = true
224			}
225		}
226	
227		if jsonOutput {
228			payload := struct {
229				File        string                                  `json:"file"`
230				Line        attributionLine                         `json:"line"`
231				Checkpoints map[string]attributionCheckpointContext `json:"checkpoints,omitempty"`
232			}{
233				File:        result.File,
234				Line:        *selected,
235				Checkpoints: checkpointContextsForLines([]attributionLine{*selected}, result.Checkpoints),
236			}
237			return writeJSON(w, payload)
238		}
239		renderAttributionLineWhy(w, result.File, *selected)
240		return nil
241	}
