243	func resolveFileAttribution(ctx context.Context, file string, fetchOnMiss bool) (*fileAttributionResult, error) {
244		repoRoot, err := paths.WorktreeRoot(ctx)
245		if err != nil {
246			return nil, errors.New("not a git repository")
247		}
248		relFile, err := normalizeAttributionPath(repoRoot, file)
249		if err != nil {
250			return nil, err
251		}
252	
253		rawLines, err := runGitBlame(ctx, repoRoot, relFile)
254		if err != nil {
255			return nil, err
256		}
257	
258		resolver, err := newAttributionResolver(ctx, fetchOnMiss)
259		if err != nil {
260			return nil, err
261		}
262		defer resolver.Close()
263	
264		result := &fileAttributionResult{
265			File:        relFile,
266			Checkpoints: make(map[string]attributionCheckpointContext),
267		}
268		for _, raw := range rawLines {
269			line := resolver.resolveLine(raw, relFile)
270			result.Lines = append(result.Lines, line)
271			for _, candidate := range line.Candidates {
272				if candidate.MetadataMissing {
273					result.Checkpoints[candidate.CheckpointID] = attributionCheckpointContext{
274						CheckpointID:    candidate.CheckpointID,
275						MetadataMissing: true,
276					}
277					continue
278				}
279				if ctx, ok := resolver.checkpointCache[candidate.CheckpointID]; ok {
280					result.Checkpoints[candidate.CheckpointID] = ctx
281				}
282			}
283		}
284		result.Summary = summarizeAttributionLines(result.Lines)
285		return result, nil
286	}
