313	func (r *attributionResolver) resolveLine(raw rawBlameLine, file string) attributionLine {
314		line := attributionLine{
315			LineNumber: raw.LineNumber,
316			CommitSHA:  raw.CommitSHA,
317			Author:     raw.Author,
318			AuthorTime: raw.AuthorTime,
319			Content:    raw.Content,
320		}
321		if raw.CommitSHA != "" && !isZeroCommit(raw.CommitSHA) {
322			line.ShortCommitSHA = shortSHA(raw.CommitSHA)
323		}
324	
325		if isZeroCommit(raw.CommitSHA) {
326			line.Authorship = attributionUncommitted
327			line.Tag = attributionTag(line.Authorship)
328			return line
329		}
330	
331		commit, err := r.commit(raw.CommitSHA)
332		if err != nil {
333			line.Authorship = attributionHuman
334			line.Tag = attributionTag(line.Authorship)
335			return line
336		}
337	
338		cpIDs := trailers.ParseAllCheckpoints(commit.Message)
339		if len(cpIDs) == 0 {
340			line.Authorship = attributionHuman
341			line.Tag = attributionTag(line.Authorship)
342			return line
343		}
344	
345		line.Authorship = attributionAI
346		var candidates []attributionCandidate
347		for _, cpID := range cpIDs {
348			ctx := r.checkpointContext(cpID, file)
349			candidate := attributionCandidate{
350				CheckpointID:    ctx.CheckpointID,
351				SessionID:       ctx.SessionID,
352				Agent:           ctx.Agent,
353				Model:           ctx.Model,
354				Prompt:          ctx.Prompt,
355				Intent:          ctx.Intent,
356				FilesTouched:    ctx.FilesTouched,
357				MetadataMissing: ctx.MetadataMissing,
358				Mixed:           ctx.Mixed,
359			}
360			candidates = append(candidates, candidate)
361			line.CheckpointIDs = append(line.CheckpointIDs, ctx.CheckpointID)
362		}
363	
364		preferred := preferredAttributionCandidate(candidates, file)
365		if preferred != nil {
366			line.CheckpointID = preferred.CheckpointID
367			line.SessionID = preferred.SessionID
368			line.Agent = preferred.Agent
369			line.Model = preferred.Model
370			line.Prompt = preferred.Prompt
371			line.Intent = preferred.Intent
372			line.MetadataMissing = preferred.MetadataMissing
373			if preferred.Mixed {
374				line.Authorship = attributionMixed
375			}
376		}
377		if len(candidates) > 0 {
378			line.Candidates = candidates
379		}
380	
381		line.Tag = attributionTag(line.Authorship)
382		return line
383	}
