385	func (r *attributionResolver) commit(sha string) (*object.Commit, error) {
386		if commit, ok := r.commitCache[sha]; ok {
387			return commit, nil
388		}
389		commit, err := r.repo.CommitObject(plumbing.NewHash(sha))
390		if err != nil {
391			return nil, err //nolint:wrapcheck // caller treats as missing attribution
392		}
393		r.commitCache[sha] = commit
394		return commit, nil
395	}
