398		key := cpID.String()
399		if ctx, ok := r.checkpointCache[key]; ok {
400			return ctx
401		}
402	
403		ctx := r.readCheckpointContext(cpID, file)
404		r.checkpointCache[key] = ctx
405		return ctx
