408	func (r *attributionResolver) readCheckpointContext(cpID id.CheckpointID, file string) attributionCheckpointContext {
409		ctx := attributionCheckpointContext{CheckpointID: cpID.String()}
410		summary, err := checkpoint.ReadCommittedCheckpoint(r.ctx, r.store, cpID)
411		if err != nil && r.fetchOnMiss {
412			if fetched, fetchErr := r.fetchCheckpointContext(cpID, file); fetchErr == nil {
413				return fetched
414			}
415		}
416		if err != nil {
417			ctx.MetadataMissing = true
418			return ctx
419		}
420	
421		ctx.FilesTouched = normalizePathSlice(summary.FilesTouched)
422		if attributionIsMixed(summary.CombinedAttribution) {
423			ctx.Mixed = true
424		}
425	
426		selected := checkpointSessionForFile{}
427		var fallback checkpointSessionForFile
428		for i := range summary.Sessions {
429			sessionCtx, readErr := r.readSessionForCheckpoint(cpID, i)
430			if readErr != nil {
431				continue
432			}
433			if sessionCtx.SessionID != "" {
434				ctx.SessionIDs = appendUniqueString(ctx.SessionIDs, sessionCtx.SessionID)
435			}
436			if attributionIsMixed(sessionCtx.Attribution) {
437				ctx.Mixed = true
438			}
439			if fallback.SessionID == "" {
440				fallback = sessionCtx
441			}
442			if selected.SessionID == "" && pathsContainFile(sessionCtx.FilesTouched, file) {
443				selected = sessionCtx
444			}
445		}
446	
447		if selected.SessionID == "" {
448			selected = fallback
449		}
450		ctx.SessionID = selected.SessionID
451		ctx.Agent = selected.Agent
452		ctx.Model = selected.Model
453		ctx.Prompt = selected.Prompt
454		ctx.Intent = selected.Intent
455		if len(selected.FilesTouched) > 0 {
456			ctx.FilesTouched = selected.FilesTouched
457		}
458		if len(ctx.FilesTouched) == 0 {
459			ctx.FilesTouched = normalizePathSlice(summary.FilesTouched)
460		}
461		return ctx
462	}
