464	func enrichAttributionLineWithFetch(ctx context.Context, file string, line *attributionLine, checkpoints map[string]attributionCheckpointContext) error {
465		if line == nil || len(line.Candidates) == 0 {
466			return nil
467		}
468		resolver, err := newAttributionResolver(ctx, true)
469		if err != nil {
470			return err
471		}
472		defer resolver.Close()
473	
474		candidates := make([]attributionCandidate, 0, len(line.Candidates))
475		authorship := attributionAI
476		for _, candidate := range line.Candidates {
477			cpID, idErr := id.NewCheckpointID(candidate.CheckpointID)
478			if idErr != nil {
479				candidates = append(candidates, candidate)
480				continue
481			}
482			cpCtx := resolver.checkpointContext(cpID, file)
483			checkpoints[cpCtx.CheckpointID] = cpCtx
484			updated := attributionCandidate{
485				CheckpointID:    cpCtx.CheckpointID,
486				SessionID:       cpCtx.SessionID,
487				Agent:           cpCtx.Agent,
488				Model:           cpCtx.Model,
489				Prompt:          cpCtx.Prompt,
490				Intent:          cpCtx.Intent,
491				FilesTouched:    cpCtx.FilesTouched,
492				MetadataMissing: cpCtx.MetadataMissing,
493				Mixed:           cpCtx.Mixed,
494			}
495			if cpCtx.Mixed {
496				authorship = attributionMixed
497			}
498			candidates = append(candidates, updated)
499		}
500		preferred := preferredAttributionCandidate(candidates, file)
501		if preferred != nil {
502			line.CheckpointID = preferred.CheckpointID
503			line.SessionID = preferred.SessionID
504			line.Agent = preferred.Agent
505			line.Model = preferred.Model
506			line.Prompt = preferred.Prompt
507			line.Intent = preferred.Intent
508			line.MetadataMissing = preferred.MetadataMissing
509		}
510		line.Candidates = candidates
511		line.Authorship = authorship
512		line.Tag = attributionTag(authorship)
513		return nil
514	}
