516	func (r *attributionResolver) fetchCheckpointContext(cpID id.CheckpointID, file string) (attributionCheckpointContext, error) {
517		lookup, err := newExplainCheckpointLookup(r.ctx)
518		if err != nil {
519			return attributionCheckpointContext{}, err
520		}
521		defer lookup.Close()
522	
523		matches, fresh := matchCheckpointPrefixWithRemoteFallback(r.ctx, io.Discard, lookup, cpID.String())
524		if fresh != lookup {
525			defer fresh.Close()
526		}
527		if len(matches) != 1 {
528			return attributionCheckpointContext{}, checkpoint.ErrCheckpointNotFound
529		}
530	
531		oldStore := r.store
532		oldFetchOnMiss := r.fetchOnMiss
533		r.store = fresh.store
534		r.fetchOnMiss = false
535		ctx := r.readCheckpointContext(cpID, file)
536		r.store = oldStore
537		r.fetchOnMiss = oldFetchOnMiss
538		return ctx, nil
539	}
