579	func runGitBlame(ctx context.Context, repoRoot, file string) ([]rawBlameLine, error) {
580		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "blame", "--line-porcelain", "--", file)
581		var stderr bytes.Buffer
582		cmd.Stderr = &stderr
583		out, err := cmd.Output()
584		if err != nil {
585			msg := strings.TrimSpace(stderr.String())
586			if msg != "" {
587				return nil, fmt.Errorf("git blame --line-porcelain %s: %w (stderr: %s)", file, err, msg)
588			}
589			return nil, fmt.Errorf("git blame --line-porcelain %s: %w", file, err)
590		}
591		return parseBlamePorcelain(string(out))
592	}
593	
594	var blameHeaderRe = regexp.MustCompile(`^([0-9a-f]{40})\s+\d+\s+(\d+)(?:\s+\d+)?$`)
595	
596	func parseBlamePorcelain(output string) ([]rawBlameLine, error) {
597		scanner := bufio.NewScanner(strings.NewReader(output))
598		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
599	
600		var current *rawBlameLine
601		var lines []rawBlameLine
602		for scanner.Scan() {
603			line := scanner.Text()
604			if match := blameHeaderRe.FindStringSubmatch(line); match != nil {
605				lineNumber, err := strconv.Atoi(match[2])
606				if err != nil {
607					return nil, fmt.Errorf("parse blame line number %q: %w", match[2], err)
608				}
609				current = &rawBlameLine{CommitSHA: match[1], LineNumber: lineNumber}
610				continue
611			}
612			if current == nil {
613				continue
614			}
615			switch {
616			case strings.HasPrefix(line, "author "):
617				current.Author = strings.TrimPrefix(line, "author ")
618			case strings.HasPrefix(line, "author-time "):
619				seconds, err := strconv.ParseInt(strings.TrimPrefix(line, "author-time "), 10, 64)
620				if err == nil {
621					t := time.Unix(seconds, 0)
622					current.AuthorTime = &t
623				}
624			case strings.HasPrefix(line, "\t"):
625				current.Content = strings.TrimPrefix(line, "\t")
626				lines = append(lines, *current)
627				current = nil
628			}
629		}
630		if err := scanner.Err(); err != nil {
631			return nil, fmt.Errorf("scan git blame output: %w", err)
632		}
633		return lines, nil
634	}
635	
636	func parseAttributionLineRange(input string) (*attributionLineRange, error) {
637		parts := strings.Split(input, "-")
638		if len(parts) > 2 || parts[0] == "" {
639			return nil, fmt.Errorf("invalid line range %q: use N or N-M", input)
640		}
641		start, err := strconv.Atoi(parts[0])
642		if err != nil || start < 1 {
643			return nil, fmt.Errorf("invalid line range %q: start must be a positive integer", input)
644		}
645		end := start
646		if len(parts) == 2 {
647			if parts[1] == "" {
648				return nil, fmt.Errorf("invalid line range %q: end must be a positive integer", input)
649			}
650			end, err = strconv.Atoi(parts[1])
651			if err != nil || end < 1 {
652				return nil, fmt.Errorf("invalid line range %q: end must be a positive integer", input)
653			}
654		}
655		if end < start {
656			return nil, fmt.Errorf("invalid line range %q: end must be >= start", input)
657		}
658		return &attributionLineRange{Start: start, End: end}, nil
659	}
660	
661	func parseAttributionWhyTarget(input string) (file string, line int, hasLine bool, err error) {
662		colon := strings.LastIndex(input, ":")
663		if colon == -1 || colon == len(input)-1 {
664			return input, 0, false, nil
665		}
666		if volume := filepath.VolumeName(input); volume != "" && colon < len(volume) {
667			return input, 0, false, nil
668		}
669		linePart := input[colon+1:]
670		parsed, parseErr := strconv.Atoi(linePart)
671		if parseErr != nil || parsed < 1 {
672			return "", 0, false, fmt.Errorf("invalid line target %q: use file:line", input)
673		}
674		return input[:colon], parsed, true, nil
675	}
