677	func normalizeAttributionPath(repoRoot, file string) (string, error) {
678		path := file
679		if !filepath.IsAbs(path) {
680			abs, err := filepath.Abs(path)
681			if err != nil {
682				return "", fmt.Errorf("resolve path %s: %w", file, err)
683			}
684			path = abs
685		}
686		canonicalRepoRoot := repoRoot
687		if resolved, err := filepath.EvalSymlinks(repoRoot); err == nil {
688			canonicalRepoRoot = resolved
689		}
690		canonicalPath := path
691		if resolved, err := filepath.EvalSymlinks(path); err == nil {
692			canonicalPath = resolved
693		}
694		rel, err := filepath.Rel(canonicalRepoRoot, canonicalPath)
695		if err != nil {
696			return "", fmt.Errorf("resolve path %s relative to repository: %w", file, err)
697		}
698		if rel == "." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) || rel == ".." {
699			return "", fmt.Errorf("%s is outside the repository", file)
700		}
701		return filepath.ToSlash(rel), nil
702	}
