704	func filterAttributionLines(lines []attributionLine, lineRange attributionLineRange) []attributionLine {
705		filtered := make([]attributionLine, 0, len(lines))
706		for _, line := range lines {
707			if line.LineNumber >= lineRange.Start && line.LineNumber <= lineRange.End {
708				filtered = append(filtered, line)
709			}
710		}
711		return filtered
712	}
