714	func checkpointContextsForLines(lines []attributionLine, contexts map[string]attributionCheckpointContext) map[string]attributionCheckpointContext {
715		if len(lines) == 0 || len(contexts) == 0 {
716			return nil
717		}
718		pruned := make(map[string]attributionCheckpointContext)
719		for _, line := range lines {
720			for _, candidate := range line.Candidates {
721				if ctx, ok := contexts[candidate.CheckpointID]; ok {
722					pruned[candidate.CheckpointID] = ctx
723				}
724			}
725			if line.CheckpointID != "" {
726				if ctx, ok := contexts[line.CheckpointID]; ok {
727					pruned[line.CheckpointID] = ctx
728				}
729			}
730		}
731		if len(pruned) == 0 {
732			return nil
733		}
734		return pruned
735	}
