737	func summarizeAttributionLines(lines []attributionLine) attributionSummary {
738		var summary attributionSummary
739		summary.TotalLines = len(lines)
740		for _, line := range lines {
741			switch line.Authorship {
742			case attributionAI:
743				summary.AILines++
744			case attributionHuman:
745				summary.HumanLines++
746			case attributionMixed:
747				summary.MixedLines++
748			case attributionUncommitted:
749				summary.UncommittedLines++
750			}
751		}
752		if summary.TotalLines > 0 {
753			summary.AIPercentage = summary.AILines * 100 / summary.TotalLines
754			summary.HumanPercentage = summary.HumanLines * 100 / summary.TotalLines
755			summary.MixedPercentage = summary.MixedLines * 100 / summary.TotalLines
756		}
757		return summary
758	}
