760	func renderAttributionBlame(w io.Writer, result *fileAttributionResult, lineFlag string) {
761		sty := newStatusStyles(w)
762		fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.bold, result.File))
763	
764		if len(result.Lines) == 0 {
765			fmt.Fprintln(w, sty.render(sty.dim, "  No lines to display."))
766			return
767		}
768	
769		lineWidth := len(strconv.Itoa(maxAttributionLineNumber(result.Lines)))
770		const checkpointColumnWidth = 21
771		fmt.Fprintf(w, "  %*s  Tag   %-12s  %-18s  %-16s  %-21s  Content\n",
772			lineWidth, "Line", "Agent", "Model", "Author", "Checkpoint/Session")
773		fmt.Fprintf(w, "  %s\n", sty.render(sty.dim, strings.Repeat("─", lineWidth+92)))
774	
775		for _, line := range result.Lines {
776			fmt.Fprintf(w, "  %s  %s  %-12s  %-18s  %-16s  %-21s  %s\n",
777				sty.render(sty.dim, fmt.Sprintf("%*d", lineWidth, line.LineNumber)),
778				renderAttributionTag(sty, line.Authorship),
779				stringutil.TruncateRunes(line.Agent, 12, ""),
780				stringutil.TruncateRunes(line.Model, 18, ""),
781				stringutil.TruncateRunes(shortAuthorName(line.Author), 16, ""),
782				stringutil.TruncateRunes(shortCheckpointSession(line), checkpointColumnWidth, ""),
783				renderAttributionContent(sty, line),
784			)
785		}
786	
787		summary := result.Summary
788		fmt.Fprintf(w, "  %s\n", sty.render(sty.dim, strings.Repeat("─", lineWidth+92)))
789		parts := []string{
790			sty.render(sty.green, fmt.Sprintf("AI: %d (%d%%)", summary.AILines, summary.AIPercentage)),
791			fmt.Sprintf("Human: %d (%d%%)", summary.HumanLines, summary.HumanPercentage),
792			sty.render(sty.yellow, fmt.Sprintf("Mixed: %d (%d%%)", summary.MixedLines, summary.MixedPercentage)),
793		}
794		if summary.UncommittedLines > 0 {
795			parts = append(parts, sty.render(sty.dim, fmt.Sprintf("Uncommitted: %d", summary.UncommittedLines)))
796		}
797		if lineFlag != "" {
798			fmt.Fprintf(w, "  %s %s %s\n\n", sty.render(sty.bold, "Summary:"), strings.Join(parts, sty.render(sty.dim, " · ")), sty.render(sty.dim, "(filtered)"))
799			return
800		}
801		fmt.Fprintf(w, "  %s %s\n\n", sty.render(sty.bold, "Summary:"), strings.Join(parts, sty.render(sty.dim, " · ")))
802	}
