804	func renderAttributionLineWhy(w io.Writer, file string, line attributionLine) {
805		sty := newStatusStyles(w)
806		fmt.Fprintf(w, "\n  %s %d in %s\n", sty.render(sty.bold, "Line"), line.LineNumber, sty.render(sty.bold, file))
807		if line.Content != "" {
808			fmt.Fprintf(w, "  %s\n\n", sty.render(sty.dim, strings.TrimRight(line.Content, "\r")))
809		}
810	
811		switch line.Authorship {
812		case attributionUncommitted:
813			fmt.Fprintf(w, "  %s\n\n", sty.render(sty.yellow, "This line is not committed yet, so Entire cannot attribute it."))
814		case attributionHuman:
815			fmt.Fprintf(w, "  Written by %s", sty.render(sty.cyan, fallbackString(shortAuthorName(line.Author), "unknown")))
816			if line.ShortCommitSHA != "" {
817				fmt.Fprintf(w, " %s commit %s", sty.render(sty.dim, "·"), sty.render(sty.dim, line.ShortCommitSHA))
818			}
819			if line.AuthorTime != nil {
820				fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), line.AuthorTime.Format("2006-01-02"))
821			}
822			fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.dim, "No Entire checkpoint is linked to the commit that last touched this line."))
823		case attributionAI, attributionMixed:
824			fmt.Fprintf(w, "  %s by %s", renderAttributionTag(sty, line.Authorship), sty.render(sty.agent, fallbackString(line.Agent, "Entire-tracked agent")))
825			if line.Model != "" {
826				fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), sty.render(sty.dim, line.Model))
827			}
828			if line.CheckpointID != "" {
829				fmt.Fprintf(w, " %s checkpoint %s", sty.render(sty.dim, "·"), sty.render(sty.cyan, line.CheckpointID))
830			}
831			if line.SessionID != "" {
832				fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), sty.render(sty.dim, shortSessionID(line.SessionID)))
833			}
834			if line.ShortCommitSHA != "" {
835				fmt.Fprintf(w, " %s commit %s", sty.render(sty.dim, "·"), sty.render(sty.dim, line.ShortCommitSHA))
836			}
837			fmt.Fprintln(w)
838			if line.Prompt != "" {
839				fmt.Fprintf(w, "  %s %q\n", sty.render(sty.bold, "Prompt:"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(line.Prompt), 160, "..."))
840			}
841			if line.Intent != "" && line.Intent != line.Prompt {
842				fmt.Fprintf(w, "  %s %q\n", sty.render(sty.bold, "Intent:"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(line.Intent), 160, "..."))
843			}
844			if line.MetadataMissing {
845				fmt.Fprintf(w, "  %s\n", sty.render(sty.yellow, "Checkpoint metadata was not found locally; showing trailer-level attribution only."))
846			}
847			if len(line.Candidates) > 1 {
848				fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, "Candidate checkpoints:"))
849				for _, candidate := range line.Candidates {
850					fmt.Fprintf(w, "  - %s", candidate.CheckpointID)
851					if candidate.SessionID != "" {
852						fmt.Fprintf(w, " session %s", shortSessionID(candidate.SessionID))
853					}
854					if candidate.Agent != "" {
855						fmt.Fprintf(w, " · %s", candidate.Agent)
856					}
857					if candidate.Prompt != "" {
858						fmt.Fprintf(w, " · %q", stringutil.TruncateRunes(stringutil.CollapseWhitespace(candidate.Prompt), 80, "..."))
859					}
860					fmt.Fprintln(w)
861				}
862			}
863			if line.CheckpointID != "" {
864				fmt.Fprintf(w, "\n  %s %s\n\n", sty.render(sty.dim, "Full context:"), sty.render(sty.cyan, "entire checkpoint explain "+line.CheckpointID))
865			} else {
866				fmt.Fprintln(w)
867			}
868		}
869	}
870	
871	func renderAttributionFileWhy(w io.Writer, result *fileAttributionResult) {
872		sty := newStatusStyles(w)
873		summary := result.Summary
874		fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, result.File))
875		fmt.Fprintf(w, "  %d lines %s %s %s %s",
876			summary.TotalLines,
877			sty.render(sty.dim, "·"),
878			sty.render(sty.green, fmt.Sprintf("%d%% AI (%d)", summary.AIPercentage, summary.AILines)),
879			sty.render(sty.dim, "·"),
880			fmt.Sprintf("%d%% human (%d)", summary.HumanPercentage, summary.HumanLines),
881		)
882		if summary.MixedLines > 0 {
883			fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), sty.render(sty.yellow, fmt.Sprintf("%d%% mixed (%d)", summary.MixedPercentage, summary.MixedLines)))
884		}
885		fmt.Fprintln(w)
886	
887		counts := checkpointLineCounts(result.Lines)
888		if len(counts) == 0 {
889			fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.dim, "No Entire checkpoints are linked to this file's current lines."))
890			return
891		}
892	
893		fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, "Top checkpoints:"))
894		for _, count := range counts {
895			ctx := result.Checkpoints[count.CheckpointID]
896			fmt.Fprintf(w, "  - %s  %d lines", sty.render(sty.cyan, count.CheckpointID), count.Lines)
897			if ctx.Agent != "" {
898				fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), ctx.Agent)
899			}
900			if ctx.SessionID != "" {
901				fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), shortSessionID(ctx.SessionID))
902			}
903			if ctx.Prompt != "" {
904				fmt.Fprintf(w, " %s %q", sty.render(sty.dim, "·"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(ctx.Prompt), 90, "..."))
905			}
906			fmt.Fprintln(w)
907		}
908		fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.dim, "Tip: entire why "+result.File+":<line> shows the prompt behind a specific line."))
909	}
910	
911	type checkpointLineCount struct {
912		CheckpointID string
913		Lines        int
914	}
915	
916	func checkpointLineCounts(lines []attributionLine) []checkpointLineCount {
917		counts := make(map[string]int)
918		for _, line := range lines {
919			if line.CheckpointID != "" {
920				counts[line.CheckpointID]++
921			}
922		}
923		out := make([]checkpointLineCount, 0, len(counts))
924		for cpID, count := range counts {
925			out = append(out, checkpointLineCount{CheckpointID: cpID, Lines: count})
926		}
927		sort.Slice(out, func(i, j int) bool {
928			if out[i].Lines == out[j].Lines {
929				return out[i].CheckpointID < out[j].CheckpointID
930			}
931			return out[i].Lines > out[j].Lines
932		})
933		if len(out) > 5 {
934			out = out[:5]
935		}
936		return out
937	}
938	
939	func renderAttributionTag(sty statusStyles, authorship attributionAuthorship) string {
940		tag := attributionTag(authorship)
941		switch authorship {
942		case attributionAI:
943			return sty.render(sty.green, tag)
944		case attributionMixed:
945			return sty.render(sty.yellow, tag)
946		case attributionUncommitted:
947			return sty.render(sty.dim, tag)
948		case attributionHuman:
949			return tag
950		default:
951			return tag
952		}
953	}
954	
955	func renderAttributionContent(sty statusStyles, line attributionLine) string {
956		content := stringutil.TruncateRunes(line.Content, 120, "...")
957		switch line.Authorship {
958		case attributionAI:
959			return sty.render(sty.green, content)
960		case attributionMixed:
961			return sty.render(sty.yellow, content)
962		case attributionUncommitted:
963			return sty.render(sty.dim, content)
964		case attributionHuman:
965			return content
966		default:
967			return content
968		}
969	}
970	
971	func maxAttributionLineNumber(lines []attributionLine) int {
972		maxLine := 1
973		for _, line := range lines {
974			if line.LineNumber > maxLine {
975				maxLine = line.LineNumber
976			}
977		}
978		return maxLine
979	}
980	
981	func attributionTag(authorship attributionAuthorship) string {
982		switch authorship {
983		case attributionAI:
984			return "[AI]"
985		case attributionMixed:
986			return "[MX]"
987		case attributionUncommitted:
988			return "[??]"
989		case attributionHuman:
990			return "[HU]"
991		default:
992			return "[HU]"
993		}
994	}
995	
996	func preferredAttributionCandidate(candidates []attributionCandidate, file string) *attributionCandidate {
997		if len(candidates) == 0 {
998			return nil
999		}
1000		for i := range candidates {
1001			if pathsContainFile(candidates[i].FilesTouched, file) {
1002				return &candidates[i]
1003			}
1004		}
1005		return &candidates[0]
1006	}
1007	
1008	func pathsContainFile(paths []string, file string) bool {
1009		normalizedFile := normalizeGitPath(file)
1010		for _, p := range paths {
1011			if normalizeGitPath(p) == normalizedFile {
1012				return true
1013			}
1014		}
1015		return false
1016	}
1017	
1018	func normalizePathSlice(paths []string) []string {
1019		out := make([]string, 0, len(paths))
1020		for _, p := range paths {
1021			if normalized := normalizeGitPath(p); normalized != "" {
1022				out = appendUniqueString(out, normalized)
1023			}
1024		}
1025		return out
1026	}
1027	
1028	func normalizeGitPath(path string) string {
1029		path = strings.TrimSpace(path)
1030		path = strings.TrimPrefix(path, "/")
1031		return filepath.ToSlash(path)
1032	}
1033	
1034	func attributionIsMixed(attr *checkpoint.InitialAttribution) bool {
1035		if attr == nil {
1036			return false
1037		}
1038		agentChanged := attr.AgentLines+attr.AgentRemoved > 0
1039		humanChanged := attr.HumanAdded+attr.HumanModified+attr.HumanRemoved > 0
1040		return agentChanged && humanChanged
1041	}
1042	
1043	func shortCheckpointSession(line attributionLine) string {
1044		if line.CheckpointID == "" {
1045			return ""
1046		}
1047		if line.SessionID == "" {
1048			return line.CheckpointID
1049		}
1050		return line.CheckpointID + "/" + shortSessionID(line.SessionID)
1051	}
1052	
1053	func shortSessionID(sessionID string) string {
1054		if len(sessionID) <= 8 {
1055			return sessionID
1056		}
1057		return sessionID[:8]
1058	}
1059	
1060	func shortSHA(sha string) string {
1061		if len(sha) <= 8 {
1062			return sha
1063		}
1064		return sha[:8]
1065	}
1066	
1067	func shortAuthorName(author string) string {
1068		author = strings.TrimSpace(author)
1069		if before, _, ok := strings.Cut(author, "<"); ok {
1070			author = strings.TrimSpace(before)
1071		}
1072		return author
1073	}
1074	
1075	func fallbackString(value, fallback string) string {
1076		if strings.TrimSpace(value) == "" {
1077			return fallback
1078		}
1079		return value
1080	}
1081	
1082	func appendUniqueString(values []string, value string) []string {
1083		if value == "" {
1084			return values
1085		}
1086		for _, existing := range values {
1087			if existing == value {
1088				return values
1089			}
1090		}
1091		return append(values, value)
1092	}
1093	
1094	func isZeroCommit(sha string) bool {
1095		return sha == "" || sha == "0000000000000000000000000000000000000000"
1096	}
1097	
1098	func writeJSON(w io.Writer, value any) error {
1099		encoder := json.NewEncoder(w)
1100		encoder.SetIndent("", "  ")
1101		if err := encoder.Encode(value); err != nil {
1102			return fmt.Errorf("encode json: %w", err)
1103		}
1104		return nil
1105	}
